# --- hand-off envelope (p6 -> p7, p8 -> p7) ---

HANDOFF_SCHEMA_VERSION = 1  # producer-agnostic: any future producer needs no consumer change


def handoff_envelope(source_system_flag, containers, **extra):
    doc = {
        "schemaVersion": HANDOFF_SCHEMA_VERSION,
        "sourceSystemFlag": source_system_flag,
        "containers": containers,
    }
    doc.update(extra)
    return doc


def validate_handoff(doc):
    """containers list from a hand-off doc, or ValueError (p7's own read checks)."""
    if not isinstance(doc, dict):
        raise ValueError("hand-off file is not a JSON object")
    version = doc.get("schemaVersion")
    if version != HANDOFF_SCHEMA_VERSION:
        raise ValueError(
            "hand-off schemaVersion %r is not the %d this pipeline reads" % (
                version, HANDOFF_SCHEMA_VERSION))
    containers = doc.get("containers")
    if not isinstance(containers, list):
        raise ValueError("hand-off file has no containers list")
    return containers


# --- XML (namespace-tolerant lookups) ---

# port of ReplaceSpecialCharsForMTC.removeSpecialChars: control chars + quotes, T-SQL safety
_SPECIAL = re.compile(r"[\x00-\x1f']")


def remove_special_chars(s):
    if s is None:
        return ""
    return _SPECIAL.sub("", str(s)).strip()


def local_name(tag):
    return tag.rsplit("}", 1)[-1] if tag else tag


def findall_local(root, tag):
    """Namespace-tolerant descendant search by local tag name (any depth under
    root, root itself included)."""
    if root is None:
        return []
    return [e for e in root.iter() if local_name(e.tag) == tag]


def findtext_local(elem, tag, default):
    """Namespace-tolerant text lookup for the first descendant matching `tag`.
    `default` is required: p6 wants "", p7 wants None."""
    if elem is None:
        return default
    for e in elem.iter():
        if local_name(e.tag) == tag:
            return e.text if e.text is not None else default
    return default


def parse_xml_safe(s):
    """ET.fromstring tolerant of blank/malformed input -> None instead of raising."""
    if not s or not s.strip():
        return None
    try:
        return ET.fromstring(s)
    except ET.ParseError:
        return None


# --- wire records ('|'-delimited SP/PL OUT-parameter output) ---

OUT_LIMIT = 32000
OVERFLOW_MARKER = "__OVERFLOW__"


def parse_wire_records(text, n_fields, what):
    """Aggregated '|'-delimited OUT-parameter output -> {idx: tuple(fields)}.
    `what` names the record kind in every raised message."""
    text = (text or "").strip()
    if not text:
        return {}
    if text.startswith(OVERFLOW_MARKER):
        raise ValueError(
            "%s output overflowed the %d-byte OUT parameter (%s); outcomes would "
            "be silently lost" % (what, OUT_LIMIT, text))
    records = {}
    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        parts = line.split("|")
        if len(parts) < n_fields:
            raise ValueError("malformed %s record: %r" % (what, line[:200]))
        try:
            idx = int(parts[0])
        except ValueError:
            raise ValueError("malformed %s record index: %r" % (what, line[:200]))
        records[idx] = tuple(parts[1:n_fields])
    return records


