# --- JSON / bool ---

def load_json(text, what, expect):
    """json.loads with a fail-loud contract: blank is a legitimate empty upstream
    (-> expect()), garbage/wrong-type is a bug (-> ValueError)."""
    if not text:
        return expect()
    try:
        value = json.loads(text)
    except (ValueError, TypeError) as exc:
        raise ValueError("%s is not valid JSON: %s" % (what, str(exc)[:200]))
    if not isinstance(value, expect):
        kind = "list" if expect is list else "object"
        raise ValueError("%s must be a JSON %s, got %s" % (
            what, kind, type(value).__name__))
    return value


def as_bool(value):
    return str(value).strip().lower() in ("true", "1", "y", "yes")


# --- exception classification ---

def is_not_found(exc):
    """True if exc represents a missing file (first run), not a real read error.
    Checks the exception class name, not message text, so a throttling error
    can't misclassify as "absent" and cause a silent unbounded replay."""
    n = exc.__class__.__name__
    return "ResourceNotFound" in n or "PathNotFound" in n or "FileNotFound" in n


_TS_FMT = "%Y-%m-%d %H:%M:%S.%f"
_TS_RE = re.compile(r"^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}\.\d{3}$")

WATERMARK_NAME = "watermark.json"
SEED_LOOKBACK_MINUTES = 30

# FMS user stamped on every call, legacy verbatim (trailing space included).
FMS_USER = "TMEAISERV "

# Legacy: 50 requirements per Location_Requirements_Update 'A' call, each
# requirement one char of type and 100 chars of text -> 50/5000 fixed widths.
REQS_PER_CALL = 50
REQ_TEXT_WIDTH = 100
REQ_TYPE_PARAM_WIDTH = REQS_PER_CALL
REQ_TEXT_PARAM_WIDTH = REQS_PER_CALL * REQ_TEXT_WIDTH

LOCATION_NUMBER_WIDTH = 7

# FMS refuses an all-zero or blank phone (DLS0313), rejecting the whole location,
# so the mapper can never emit one even when the configured default is blank.
FALLBACK_PHONE = "0000000001"

# DB2 for i truncates SIGNAL SET MESSAGE_TEXT at 70 bytes. The Lookup always ends
# in SIGNAL and shows failed; the message text is the only outcome channel.
SIGNAL_SQLSTATE = "75005"
OK_MARKER = "P9OK"
ERR_MARKER = "P9ERR"
MESSAGE_TEXT_MAX = 70

# Markers are assembled from fragments so neither appears as a contiguous run in
# the statement text; an echoed statement containing both would read as failed.
_OK_SQL = "'P9' || 'OK'"
_ERR_SQL = "'P9' || 'ERR '"

# A Script output over ~3-4 MB returns empty instead of failing, so the assembled
# blocks are size-checked here where the failure can still be loud.
MAX_CALLS_BYTES = 1500000

# LM reads end in a sentinel row; its absence means the set was truncated or
# emptied, which would otherwise advance the watermark over unsent locations.
SENTINEL_ID = "-1"

# Resume point inside a same-timestamp group. -1 means "none": the window then
# starts strictly after beginTs, which is what a pre-composite watermark meant.
NO_BEGIN_ID = -1

# Window is trigger time converted to Central; if LocationManagement's server
# clock is not Central, every row falls outside it and the run is a green no-op.
MAX_CLOCK_SKEW_MINUTES = 20


def _watermark_path(stagingFolder):
    """Watermark lives at the staging root, not inside a per-run folder."""
    return (stagingFolder or "").rstrip("/") + "/" + WATERMARK_NAME


def _valid_ts(s):
    if not isinstance(s, str):
        return False
    if not _TS_RE.match(s):
        return False
    try:
        _parse_ts(s)
        return True
    except Exception:
        return False


def _parse_ts(s):
    return datetime.strptime(s, _TS_FMT)


def _fmt_ts(dt):
    return dt.strftime("%Y-%m-%d %H:%M:%S.") + "%03d" % (dt.microsecond // 1000)


def _window(beginTs="", endTs="", seeded=False, error="", beginId=NO_BEGIN_ID):
    return {"beginTs": beginTs, "endTs": endTs, "seeded": seeded, "error": error,
            "beginId": beginId}


def _compute_window(rawJson, endTs):
    """Window is [last run, this run]; malformed data errors rather than seeds an unbounded span."""
    if not _valid_ts(endTs):
        return _window(error="endTs is not 'yyyy-MM-dd HH:mm:ss.SSS': %r" % (endTs,))
    end = _parse_ts(endTs)

    if rawJson is None or not rawJson.strip():
        return _window(_fmt_ts(end - timedelta(minutes=SEED_LOOKBACK_MINUTES)),
                       endTs, True)
    try:
        doc = json.loads(rawJson)
    except Exception as exc:
        return _window(error="watermark unparseable: %s" % str(exc)[:200])
    if not isinstance(doc, dict):
        return _window(error="watermark is not a JSON object")
    begin = doc.get("nextBeginTs")
    if not _valid_ts(begin):
        return _window(error="watermark nextBeginTs invalid: %r" % (begin,))
    if _parse_ts(begin) > end:
        return _window(error="window begin %s is after end %s (clock moved backwards "
                             "or the watermark is ahead of the trigger time)"
                             % (begin, endTs))
    return _window(begin, endTs, False, beginId=_as_begin_id(doc.get("nextBeginId")))


def _as_begin_id(value):
    """A watermark written before the composite resume point has no id; absent or
    unusable both mean NO_BEGIN_ID, which reproduces the old strictly-after window."""
    if value is None or value == "":
        return NO_BEGIN_ID
    try:
        parsed = int(value)
    except Exception:
        return NO_BEGIN_ID
    return parsed if parsed >= 0 else NO_BEGIN_ID


def _resume_point(rows):
    """Highest (ChangedTs, LocationId) actually read; where the next window resumes."""
    best = None
    for row in rows:
        ts = _s(row.get("ChangedTs")).strip()
        if not _valid_ts(ts):
            continue
        try:
            loc = int(_s(row.get("LocationId")).strip())
        except Exception:
            continue
        key = (ts, loc)
        if best is None or key > best:
            best = key
    return best


def _read_text(files, path):
    """(text, absent); absent only for not-found, other errors must not seed a wide-open window."""
    try:
        return files.get_file_client(path).download_file().readall().decode("utf-8"), False
    except Exception as exc:
        if is_not_found(exc):
            return None, True
        raise


def _write_text(files, path, text):
    files.get_file_client(path).upload_data(text.encode("utf-8"), overwrite=True)


# ---------------------------------------------------------------- field mapping

def _s(value):
    """LM value as a string; None becomes blank, not the literal 'null' Java wrote."""
    if value is None:
        return ""
    return str(value)


def _fit(value, width):
    return _s(value)[:width].ljust(width)


def _location_number(locationId):
    """Zero-pads id to 7 digits; over 7 returns None instead of colliding with another location."""
    raw = _s(locationId).strip()
    if not raw.isdigit():
        return None
    if len(raw) > LOCATION_NUMBER_WIDTH:
        return None
    return raw.rjust(LOCATION_NUMBER_WIDTH, "0")


def _country(value):
    """Only US maps to USA; everything else passes through padded to 3, as legacy did."""
    raw = _s(value)
    if raw.strip().upper() == "US":
        raw = "USA"
    return _fit(raw, 3)


def _postal(value):
    """Blank postal is nine zeroes, dashes stripped, truncated to 9 unlike legacy's overflow."""
    raw = _s(value).strip()
    if not raw:
        return "000000000"
    return _fit(raw.replace("-", ""), 9)


def _is_number(raw):
    try:
        float(raw)
        return True
    except (TypeError, ValueError):
        return False


def _is_all_zero(raw):
    """All-digit zero via isdigit, not the float gate, which also reads '0.0'/'0e5' as zero."""
    return raw.isdigit() and int(raw) == 0


def _phone(value, default_phone):
    """Blank, non-numeric or zero falls to default then FALLBACK_PHONE (FMS refuses those)."""
    raw = _s(value).strip().replace(" ", "").replace("-", "")
    if not raw or not _is_number(raw) or _is_all_zero(raw):
        raw = _s(default_phone).strip().replace(" ", "").replace("-", "")
    if not raw or _is_all_zero(raw):
        raw = FALLBACK_PHONE
    if len(raw) > 10:
        raw = raw[-10:]
    return raw.ljust(10)


def _fax(value):
    """Blank fax is ten zeroes not blanks, as legacy passed it; dashes strip before the cut."""
    raw = _s(value).strip().replace(" ", "").replace("-", "")
    if not raw:
        return "0000000000"
    return _fit(raw, 10)


def _status(value):
    """First character: '0' is Inactive, else Active, matching the legacy default for blank."""
    raw = _s(value).strip()
    if not raw:
        return "A"
    return "I" if raw[0] == "0" else "A"


def _parent(value):
    """Blank parent is seven zeroes; present ones truncate to 7, unpadded (KNOWN_GAPS.md)."""
    raw = _s(value).strip()
    if not raw:
        return "0000000"
    return _fit(raw, LOCATION_NUMBER_WIDTH)


def _facility_key(value, width):
    """FacilityDropsite/FacilityLocaleKey arrive pre-split by the LM query; only width applies."""
    raw = _s(value).strip()
    if not raw:
        return "".ljust(width)
    return _fit(raw, width)


def map_location(row, default_phone):
    """The 20 input parameters of Fmslib.Add_Update_Locations, in call order.
    Returns (None, None) when the id cannot be expressed as 7 digits."""
    number = _location_number(row.get("LocationId"))
    if number is None:
        return None, None
    name = _s(row.get("LocationName"))
    city = _s(row.get("City"))
    state = _s(row.get("State")).strip()
    params = [
        number,                                          # 1  location
        _fit(name, 30),                                  # 2  name
        _fit(row.get("StreetAddress1"), 30),             # 3  address 1
        _fit(row.get("StreetAddress2"), 30),             # 4  address 2
        _fit(city, 18),                                  # 5  city
        _fit(state, 2),                                  # 6  state
        _country(row.get("Country")),                    # 7  country
        _postal(row.get("PostalCode")),                  # 8  postal code
        _phone(row.get("Phone"), default_phone),         # 9  phone
        _fit(row.get("ContactName"), 30),                # 10 contact name
        _fax(row.get("Fax")),                            # 11 fax
        _status(row.get("Status")),                      # 12 status
        _fit(row.get("LocationCategoryName"), 10),       # 13 location type
        _fit(row.get("LocationCategoryDesc"), 30),       # 14 location type description
        _parent(row.get("ParentId")),                    # 15 dual location parent
        _fit(name, 28),                                  # 16 facility name
        _fit(city, 28),                                  # 17 facility city
        _facility_key(row.get("FacilityDropsite"), 7),   # 18 facility drop site key
        _facility_key(row.get("FacilityLocaleKey"), 9),  # 19 facility locale key
        FMS_USER,                                        # 20 user
    ]
    return params, number


# ------------------------------------------------------------ DB2 block assembly

_CTRL_RE = re.compile(r"[\r\n\t\x00-\x1f]")


def _lit(value):
    """DB2 string literal; control chars become spaces, quotes double after padding.
    Trailing blanks drop: every FMS proc parameter is CHAR, so DB2 pads them back."""
    return "'" + _CTRL_RE.sub(" ", value).rstrip(" ").replace("'", "''") + "'"


def _call(proc, params):
    """Out params clear before every call, so a skipped proc isn't blamed for the last error."""
    return "SET V_ERRCODE = ''; SET V_ERRSTR = ''; CALL %s(%s, V_ERRCODE, V_ERRSTR);" % (
        proc, ", ".join("NULL" if p is None else _lit(p) for p in params))


def _capture(step):
    """Keeps the first error; an Add_Update_Locations failure explains what follows."""
    return ("IF V_MSG = %s AND (COALESCE(TRIM(V_ERRCODE), '') <> '' "
            "OR COALESCE(TRIM(V_ERRSTR), '') <> '') THEN "
            "SET V_MSG = LEFT(%s || '%s ' || TRIM(V_ERRCODE) || ' ' || TRIM(V_ERRSTR), %d); "
            "END IF;") % (_OK_SQL, _ERR_SQL, step, MESSAGE_TEXT_MAX)


def _requirement_batches(requirements):
    """Legacy batching: 50 reqs/call, types in one 50-char param, texts in one 5000-char param."""
    batches = []
    for start in range(0, len(requirements), REQS_PER_CALL):
        chunk = requirements[start:start + REQS_PER_CALL]
        types = ""
        texts = ""
        for req in chunk:
            req_type = _s(req.get("ReqType"))
            types += req_type if len(req_type) == 1 else " "
            texts += _fit(req.get("ReqText"), REQ_TEXT_WIDTH)
        batches.append((types.ljust(REQ_TYPE_PARAM_WIDTH),
                        texts.ljust(REQ_TEXT_PARAM_WIDTH)))
    return batches


# ADDLIBLE, CHGJOB INQMSGRPY(*DFT) and the CALL must run in one compound statement,
# one ODBC execute per QSQSRVR job, or a missing library hangs the job in MSGW.
_FMS_LIBL_PREFIX = (
    "BEGIN DECLARE CONTINUE HANDLER FOR SQLEXCEPTION BEGIN END; "
    "CALL QSYS2.QCMDEXC('CHGJOB INQMSGRPY(*DFT)'); "
    "CALL QSYS2.QCMDEXC('ADDLIBLE LIB(FMSSEC) POSITION(*FIRST)'); END; ")


def build_location_block(row, requirements, fmsLibrary, default_phone):
    """One location's FMS work as one dynamic compound statement; split across
    calls, a failure between 'D' and 'A' would leave partial requirements in FMS."""
    params, number = map_location(row, default_phone)
    if params is None:
        return "", "location_id_unmappable"

    add_update = "%s.ADD_UPDATE_LOCATIONS" % fmsLibrary
    req_update = "%s.LOCATION_REQUIREMENTS_UPDATE" % fmsLibrary

    body = [_call(add_update, params), _capture("AU")]

    # Legacy calls 'D' only inside the requirements loop, so a location whose
    # requirements were all removed in LM never gets one; kept as-is, see KNOWN_GAPS.md.
    if requirements:
        body.append(_call(req_update, [
            "D", number, " " * REQ_TYPE_PARAM_WIDTH, " " * REQ_TEXT_PARAM_WIDTH,
            FMS_USER]))
        body.append(_capture("RD"))
        for types, texts in _requirement_batches(requirements):
            body.append(_call(req_update, ["A", number, types, texts, FMS_USER]))
            body.append(_capture("RA"))

    sql = ("BEGIN "
           "DECLARE V_ERRCODE VARCHAR(256) DEFAULT ''; "
           "DECLARE V_ERRSTR VARCHAR(1024) DEFAULT ''; "
           "DECLARE V_MSG VARCHAR(%d) DEFAULT ''; "
           "%s"
           "SET V_MSG = %s; "
           "%s "
           "SIGNAL SQLSTATE '%s' SET MESSAGE_TEXT = V_MSG; "
           "END") % (MESSAGE_TEXT_MAX, _FMS_LIBL_PREFIX, _OK_SQL,
                     " ".join(body), SIGNAL_SQLSTATE)
    return sql, ""


# --------------------------------------------------------------- LM result sets

def _rows(rawJson, what):
    """Script result as dicts; raises on non-array since an oversized output returns empty."""
    try:
        parsed = json.loads(rawJson) if rawJson else []
    except Exception as exc:
        raise ValueError("%s result set is not JSON: %s" % (what, str(exc)[:200]))
    if parsed is None:
        parsed = []
    if not isinstance(parsed, list):
        raise ValueError("%s result set is not a JSON array" % what)
    return [r for r in parsed if isinstance(r, dict)]


def _split_sentinel(rows, idField, what):
    """(dataRows, sentinelRow); sentinel carries the server clock; its absence means truncation."""
    data = []
    sentinel = None
    for row in rows:
        if _s(row.get(idField)).strip() == SENTINEL_ID:
            sentinel = row
        else:
            data.append(row)
    if sentinel is None:
        raise ValueError("%s result set has no sentinel row -- the payload was "
                         "truncated or silently emptied" % what)
    return data, sentinel


def _group_requirements(rows):
    """Requirements keyed by LocationId; LM orders them so a replay repeats the 50-slot layout."""
    grouped = {}
    for row in rows:
        key = _s(row.get("LocationId")).strip()
        grouped.setdefault(key, []).append(row)
    return grouped


def _max_ts(rows):
    """Newest ChangedTs read."""
    seen = [_s(r.get("ChangedTs")).strip() for r in rows]
    seen = [s for s in seen if _valid_ts(s)]
    return max(seen) if seen else ""


def _build_result(**kw):
    out = {"calls": [], "skipped": [], "locationCount": 0, "requirementCount": 0,
           "maxTs": "", "serverTs": "", "capped": False, "bytes": 0, "error": "",
           "callCount": 0, "nextBeginTs": "", "nextBeginId": NO_BEGIN_ID}
    out.update(kw)
    return out


def _clock_skew_error(serverTs, endTs):
    """Non-empty when window and LocationManagement clocks disagree past tolerance."""
    if not _valid_ts(endTs):
        return ""
    if not _valid_ts(serverTs):
        return ("the locations sentinel carried no usable server clock (%r), so a "
                "timezone mismatch cannot be ruled out" % (serverTs,))
    skew = abs((_parse_ts(serverTs) - _parse_ts(endTs)).total_seconds()) / 60.0
    if skew > MAX_CLOCK_SKEW_MINUTES:
        return ("LocationManagement's clock reads %s while this run's window ends at "
                "%s, %.0f minutes apart -- the window is being built in a different "
                "timezone from the columns it filters, so it can match nothing"
                % (serverTs, endTs, skew))
    return ""


def _build_calls(locationsJson, requirementsJson, fmsLibrary, defaultPhone,
                 maxLocations, endTs=""):
    if not _s(fmsLibrary).strip():
        return _build_result(error="fmsLibrary is blank")

    locations, loc_sentinel = _split_sentinel(
        _rows(locationsJson, "locations"), "LocationId", "locations")
    requirements, _ = _split_sentinel(
        _rows(requirementsJson, "requirements"), "LocationId", "requirements")

    server_ts = _s(loc_sentinel.get("ChangedTs")).strip()
    skew = _clock_skew_error(server_ts, endTs)
    if skew:
        return _build_result(error=skew, serverTs=server_ts)

    grouped = _group_requirements(requirements)
    calls = []
    skipped = []
    for row in locations:
        sql, skip = build_location_block(row, grouped.get(
            _s(row.get("LocationId")).strip(), []), fmsLibrary, defaultPhone)
        if skip:
            skipped.append({"locationId": _s(row.get("LocationId")),
                            "reason": skip})
            continue
        calls.append({"locationId": _s(row.get("LocationId")),
                      "locationName": _s(row.get("LocationName"))[:60],
                      "requirementCount": len(grouped.get(
                          _s(row.get("LocationId")).strip(), [])),
                      "sql": sql})

    size = len(json.dumps(calls))
    if size > MAX_CALLS_BYTES:
        return _build_result(
            error="assembled calls are %d bytes, over the %d limit -- lower "
                  "max_locations_per_run" % (size, MAX_CALLS_BYTES))

    max_ts = _max_ts(locations)
    capped = maxLocations > 0 and len(locations) >= maxLocations
    resume = _resume_point(locations)

    # Capped: resume inside the group just consumed so a same-timestamp burst drains
    # across runs; otherwise the next window starts strictly after endTs.
    if capped and resume:
        next_ts, next_id = resume[0], resume[1]
    else:
        next_ts, next_id = endTs, NO_BEGIN_ID

    return _build_result(
        calls=calls, skipped=skipped, locationCount=len(locations),
        requirementCount=len(requirements), maxTs=max_ts, serverTs=server_ts,
        capped=capped, bytes=size, callCount=len(calls),
        nextBeginTs=next_ts, nextBeginId=next_id)


# ------------------------------------------------------------------- item logs

_EMPTY_JSON = "{}"


def _item_record(runId, pipeline, itemType, itemId, outcome, errorCode,
                 errorMessage, details, ts):
    """One etl_item_log row matching udf_etl_logging's columns, JSON-string fields included."""
    return {
        "run_id": runId or "",
        "pipeline": pipeline,
        "item_type": itemType,
        "item_id": itemId or "",
        "ts_utc": ts,
        "outcome": outcome or "",
        "target": "",
        "file_path": "",
        "error_code": errorCode or "",
        "error_message": errorMessage or "",
        "step_statuses": _EMPTY_JSON,
        "details": json.dumps(details),
        "debug": _EMPTY_JSON,
        "log_day": ts[:10] if len(ts) >= 10 else "",
        "log_hour": ts[11:13] if len(ts) >= 13 else "",
    }


# Known-error catalog (docs/PIPELINE_GUIDELINES.md "Known-error catalog"), matched against the
# FMS proc's ERR detail.
KNOWN_BUSINESS_ERRORS = ()


def _is_known_business_error(msg):
    return any(p in (msg or "").lower() for p in KNOWN_BUSINESS_ERRORS)


def classify_outcome(rawMessage):
    """(outcome, errorCode, errorMessage). The block always ends in SIGNAL, so the
    message text is the only channel: OK/ERR markers, else DB2 itself failed."""
    msg = _s(rawMessage)
    if OK_MARKER in msg and ERR_MARKER not in msg:
        return "sent", "", ""
    if ERR_MARKER in msg:
        start = msg.index(ERR_MARKER)
        detail = msg[start:start + MESSAGE_TEXT_MAX].strip()
        parts = detail.split(None, 2)
        step = parts[1] if len(parts) > 1 else ""
        code = parts[2].split(None, 1)[0] if len(parts) > 2 else ""
        return "fms_error", ("%s_%s" % (step, code)).strip("_"), detail
    return "technical", "db2_call_failed", msg[:1000]


def _summarise(outcomes):
    counts = {}
    for o in outcomes:
        counts[o["outcome"]] = counts.get(o["outcome"], 0) + 1
    return counts


def _digest_body(runId, beginTs, endTs, outcomes, skipped):
    """Plain-text digest of what didn't cleanly reach FMS, known warnings excluded; empty
    means no errors mail is sent."""
    bad = [o for o in outcomes if o["outcome"] not in ("sent", "business_warning")]
    if not bad and not skipped:
        return ""
    lines = ["9_pl_LM_To_FMS_Locations reported location failures.", "",
             "Run: %s" % runId, "Window: %s .. %s" % (beginTs, endTs),
             "Locations attempted: %d, failed: %d, skipped: %d"
             % (len(outcomes), len(bad), len(skipped)), ""]
    lines.extend(_outcome_lines(bad))
    for s in skipped:
        lines.append("  %s  %s" % (s.get("locationId", ""), s.get("reason", "")))
    lines.append("")
    lines.append("The watermark advanced: these locations are NOT retried "
                 "automatically. Re-run with overrideBeginTs to replay the window.")
    return "\n".join(lines)


def _warning_body(runId, beginTs, endTs, outcomes):
    """Plain-text list of known FMS refusals; empty means no warnings mail is sent."""
    warns = [o for o in outcomes if o["outcome"] == "business_warning"]
    if not warns:
        return ""
    return "\n".join(["9_pl_LM_To_FMS_Locations known warnings (no action needed).", "",
                      "Run: %s" % runId, "Window: %s .. %s" % (beginTs, endTs), ""]
                     + _outcome_lines(warns))


def _outcome_lines(rows):
    return ["  %s  %s  %s  %s" % (o.get("locationId", ""), o["outcome"], o.get("errorCode", ""),
                                  o.get("errorMessage", "")[:200]) for o in rows]


def _message_of(entry):
    """SIGNAL text, base64-encoded since a DB2 error carries quotes/newlines that break JSON."""
    raw = entry.get("messageB64")
    if raw:
        try:
            return base64.b64decode(_s(raw)).decode("utf-8", "replace")
        except Exception:
            return _s(raw)
    return _s(entry.get("message"))


def _parse_outcomes(outcomesJson, defaultTs):
    """One entry per ForEach iteration, each carrying the location and raw Lookup error message."""
    try:
        entries = json.loads(outcomesJson) if outcomesJson else []
    except Exception as exc:
        raise ValueError("outcomesJson is not JSON: %s" % str(exc)[:200])
    if not isinstance(entries, list):
        raise ValueError("outcomesJson is not a JSON array")
    parsed = []
    for entry in entries:
        if isinstance(entry, str):
            try:
                entry = json.loads(entry)
            except Exception:
                entry = {"locationId": "", "message": entry}
        if not isinstance(entry, dict):
            continue
        outcome, code, message = classify_outcome(_message_of(entry))
        if outcome == "fms_error" and _is_known_business_error(message):
            outcome = "business_warning"
        parsed.append({"locationId": _s(entry.get("locationId")),
                       "requirementCount": entry.get("requirementCount"),
                       "outcome": outcome, "errorCode": code,
                       "errorMessage": message,
                       "ts": _s(entry.get("ts")) or defaultTs})
    return parsed



# ============================================================================
# NiFi 2.x Python processors for the LM -> FMS locations flow.
# Everything above this banner is sliced verbatim from the Fabric UDF by
# build_nifi.py, so mapping/assembly/classification cannot drift from p9.
# ============================================================================
import os
import uuid as _uuid
from zoneinfo import ZoneInfo

from nifiapi.flowfiletransform import FlowFileTransform, FlowFileTransformResult
from nifiapi.properties import PropertyDescriptor, StandardValidators
from nifiapi.relationship import Relationship

_CENTRAL = ZoneInfo("America/Chicago")
_VERSION = "0.1.0"

STAGING_DIR = PropertyDescriptor(
    name="Staging Directory",
    description="Folder holding watermark.json (stand-in for the lakehouse staging folder).",
    required=True, validators=[StandardValidators.NON_EMPTY_VALIDATOR])


def _attr(flowfile, name, default=""):
    v = flowfile.getAttribute(name)
    return default if v is None else v


def _fail(message, **extra):
    attrs = {"lm.error": str(message)[:2000]}
    attrs.update(extra)
    return FlowFileTransformResult(relationship="failure", attributes=attrs)


class ComputeLmWindow(FlowFileTransform):
    """ReadWatermark + CheckWatermarkError: emits the window as attributes and as
    sql.args.N.* so ExecuteSQLRecord binds them to the LM query's ? markers."""

    class Java:
        implements = ["org.apache.nifi.python.processor.FlowFileTransform"]

    class ProcessorDetails:
        version = _VERSION
        description = "Computes the LocationManagement change window from watermark.json (p9 readWatermark)."
        tags = ["mtc", "lm", "fms", "watermark"]

    OVERRIDE = PropertyDescriptor(
        name="Override Begin Ts",
        description="yyyy-MM-dd HH:mm:ss.SSS; replays from here without reading watermark.json.",
        required=False)
    MAX_LOCATIONS = PropertyDescriptor(
        name="Max Locations Per Run", description="TOP (n) cap on the LM read.",
        required=True, default_value="400", validators=[StandardValidators.POSITIVE_INTEGER_VALIDATOR])

    def __init__(self, **kwargs):
        super().__init__()

    def getPropertyDescriptors(self):
        return [STAGING_DIR, self.OVERRIDE, self.MAX_LOCATIONS]

    def transform(self, context, flowfile):
        staging = context.getProperty(STAGING_DIR).getValue()
        override = (context.getProperty(self.OVERRIDE).getValue() or "").strip()
        max_locations = context.getProperty(self.MAX_LOCATIONS).getValue()
        from datetime import datetime as _dt
        end_ts = _fmt_ts(_dt.now(_CENTRAL).replace(tzinfo=None))
        try:
            if override:
                if not _valid_ts(override):
                    return _fail("WATERMARK_UNUSABLE: overrideBeginTs %r is not yyyy-MM-dd HH:mm:ss.SSS" % override)
                window = _window(override, end_ts, False)
            else:
                path = os.path.join(staging, WATERMARK_NAME)
                raw = None
                if os.path.exists(path):
                    with open(path, encoding="utf-8") as fh:
                        raw = fh.read()
                window = _compute_window(raw, end_ts)
        except Exception as exc:
            return _fail("WATERMARK_UNUSABLE: watermark read failed: %s" % str(exc)[:300])
        if window["error"]:
            return _fail("WATERMARK_UNUSABLE: %s. LocationManagement was NOT read." % window["error"])
        return FlowFileTransformResult(relationship="success", contents=b"", attributes={
            "lm.runId": _attr(flowfile, "uuid", str(_uuid.uuid4())),
            "lm.beginTs": window["beginTs"],
            "lm.endTs": window["endTs"],
            "lm.beginId": str(window["beginId"]),
            "lm.seeded": str(window["seeded"]).lower(),
            "sql.args.1.type": "12", "sql.args.1.value": window["beginTs"],
            "sql.args.2.type": "12", "sql.args.2.value": window["endTs"],
            "sql.args.3.type": "4", "sql.args.3.value": str(window["beginId"]),
            "sql.args.4.type": "4", "sql.args.4.value": str(max_locations),
        })


class BuildFmsLocationCalls(FlowFileTransform):
    """BuildLocationCalls + CheckBuildError. Input is the LM record set as a JSON
    array whose RequirementsJson column nests each location's requirements."""

    class Java:
        implements = ["org.apache.nifi.python.processor.FlowFileTransform"]

    class ProcessorDetails:
        version = _VERSION
        description = "Assembles one DB2 compound statement per LM location (p9 buildLocationCalls)."
        tags = ["mtc", "lm", "fms", "db2"]

    FMS_LIBRARY = PropertyDescriptor(name="FMS Library", description="FMS proc library.",
                                     required=True, default_value="FMSLIB",
                                     validators=[StandardValidators.NON_EMPTY_VALIDATOR])
    DEFAULT_PHONE = PropertyDescriptor(name="Default Contact Phone", description="Phone for blank/zero LM phones.",
                                       required=True, default_value="0000000001")
    MAX_LOCATIONS = ComputeLmWindow.MAX_LOCATIONS
    EMPTY = Relationship(name="empty", description="Window held no sendable locations; go straight to finalize.")

    def __init__(self, **kwargs):
        super().__init__()

    def getPropertyDescriptors(self):
        return [self.FMS_LIBRARY, self.DEFAULT_PHONE, self.MAX_LOCATIONS]

    def getRelationships(self):
        return [self.EMPTY]

    def transform(self, context, flowfile):
        try:
            rows = json.loads(flowfile.getContentsAsBytes().decode("utf-8") or "[]")
            if isinstance(rows, dict):
                rows = [rows]
            locations, requirements = [], []
            for row in rows:
                nested = row.pop("RequirementsJson", None)
                locations.append(row)
                if nested:
                    requirements.extend(json.loads(nested))
            # the nested shape cannot truncate requirements apart from locations
            requirements.append({"LocationId": SENTINEL_ID})
            result = _build_calls(json.dumps(locations), json.dumps(requirements),
                                  context.getProperty(self.FMS_LIBRARY).getValue(),
                                  context.getProperty(self.DEFAULT_PHONE).getValue(),
                                  int(context.getProperty(self.MAX_LOCATIONS).getValue()),
                                  _attr(flowfile, "lm.endTs"))
        except Exception as exc:
            return _fail("BUILD_FAILED: %s" % str(exc)[:500])
        if result["error"]:
            return _fail("BUILD_FAILED: %s. Nothing was sent." % result["error"])
        attrs = {
            "lm.callCount": str(result["callCount"]),
            "lm.locationCount": str(result["locationCount"]),
            "lm.requirementCount": str(result["requirementCount"]),
            "lm.capped": str(result["capped"]).lower(),
            "lm.nextBeginTs": result["nextBeginTs"],
            "lm.nextBeginId": str(result["nextBeginId"]),
            "lm.skippedJson": json.dumps(result["skipped"]),
        }
        rel = "success" if result["calls"] else "empty"
        return FlowFileTransformResult(relationship=rel, attributes=attrs,
                                       contents=json.dumps(result["calls"]).encode("utf-8"))


class FinalizeLmLocations(FlowFileTransform):
    """FinalizeLocations: classifies each DB2 SIGNAL text and writes item-log rows as content."""

    class Java:
        implements = ["org.apache.nifi.python.processor.FlowFileTransform"]

    class ProcessorDetails:
        version = _VERSION
        description = "Classifies FMS outcomes and builds item log + digest (p9 finalizeLocations)."
        tags = ["mtc", "lm", "fms", "logging"]

    def __init__(self, **kwargs):
        super().__init__()

    def getPropertyDescriptors(self):
        return []

    def transform(self, context, flowfile):
        run_id = _attr(flowfile, "lm.runId")
        begin_ts, end_ts = _attr(flowfile, "lm.beginTs"), _attr(flowfile, "lm.endTs")
        try:
            merged = json.loads(flowfile.getContentsAsBytes().decode("utf-8") or "[]")
            entries = [{"locationId": e.get("lm.locationId", ""),
                        "requirementCount": int(e.get("lm.requirementCount") or 0),
                        "message": e.get("executesql.error.message", "")}
                       for e in merged if isinstance(e, dict) and "lm.locationId" in e]
            expected = int(_attr(flowfile, "lm.callCount", "0"))
            if len(entries) != expected:
                return _fail("expected %d location outcome(s), got %d -- watermark NOT advanced"
                             % (expected, len(entries)))
            ts = end_ts if _valid_ts(end_ts) else _fmt_ts(datetime.utcnow())
            outcomes = _parse_outcomes(json.dumps(entries), ts)
            skipped = json.loads(_attr(flowfile, "lm.skippedJson", "[]") or "[]")
        except Exception as exc:
            return _fail("FINALIZE_FAILED: %s" % str(exc)[:500])

        pipeline = "lm-to-fms-locations"
        items = [_item_record(run_id, pipeline, "location", o["locationId"], o["outcome"], o["errorCode"],
                              o["errorMessage"], {"requirementCount": o.get("requirementCount"),
                                                  "windowBegin": begin_ts, "windowEnd": end_ts}, o["ts"])
                 for o in outcomes]
        items += [_item_record(run_id, pipeline, "location", _s(s.get("locationId")), _s(s.get("reason")),
                               _s(s.get("reason")), "", {"windowBegin": begin_ts, "windowEnd": end_ts}, ts)
                  for s in skipped if isinstance(s, dict)]
        counts = _summarise(outcomes)
        technical = counts.get("technical", 0)
        digest = _digest_body(run_id, begin_ts, end_ts, outcomes, skipped)
        return FlowFileTransformResult(relationship="success", contents=json.dumps(items).encode("utf-8"),
                                       attributes={
            "filename": "items.json",
            "lm.sent": str(counts.get("sent", 0)),
            "lm.fmsErrors": str(counts.get("fms_error", 0)),
            "lm.technical": str(technical),
            "lm.skipped": str(len(skipped)),
            "lm.hasFailures": str(bool(digest)).lower(),
            "lm.digestBody": digest,
            "lm.nextBeginTs": "" if technical else _attr(flowfile, "lm.nextBeginTs"),
            "lm.nextBeginId": str(NO_BEGIN_ID if technical else _as_begin_id(_attr(flowfile, "lm.nextBeginId"))),
            "lm.watermarkHeld": str(bool(technical)).lower(),
        })


class AdvanceLmWatermark(FlowFileTransform):
    """AdvanceWatermark: the commit point. Blank nextBeginTs (technical failure) routes to failure."""

    class Java:
        implements = ["org.apache.nifi.python.processor.FlowFileTransform"]

    class ProcessorDetails:
        version = _VERSION
        description = "Writes watermark.json after a run consumed its window (p9 advanceWatermark)."
        tags = ["mtc", "lm", "fms", "watermark"]

    def __init__(self, **kwargs):
        super().__init__()

    def getPropertyDescriptors(self):
        return [STAGING_DIR]

    def transform(self, context, flowfile):
        next_ts = _attr(flowfile, "lm.nextBeginTs")
        if not _valid_ts(next_ts):
            return _fail("WATERMARK_ADVANCE_FAILED: nextBeginTs %r unusable (held by a technical failure?); "
                         "the next run re-reads this window" % next_ts)
        doc = {"nextBeginTs": next_ts, "nextBeginId": _as_begin_id(_attr(flowfile, "lm.nextBeginId")),
               "runId": _attr(flowfile, "lm.runId")}
        staging = context.getProperty(STAGING_DIR).getValue()
        try:
            os.makedirs(staging, exist_ok=True)
            tmp = os.path.join(staging, WATERMARK_NAME + ".tmp")
            with open(tmp, "w", encoding="utf-8") as fh:
                fh.write(json.dumps(doc))
            os.replace(tmp, os.path.join(staging, WATERMARK_NAME))
        except Exception as exc:
            return _fail("WATERMARK_ADVANCE_FAILED: %s" % str(exc)[:300])
        return FlowFileTransformResult(relationship="success")
